 a2_ensure_dir():\\n    if os.path.isdir(\\\"archive\\\"):\\n        print(\\\"  A2 SKIP: archive already correct (no change)\\\")\\n    else:\\n        os.mkdir(\\\"archive\\\")\\n        print(\\\"  A2 CREATE: archive/ (empty directory)\\\")\\n\\n\\ndef fingerprint():\\n    state = []\\n    for p, kind in [(\\\"notes.txt\\\", \\\"file\\\"), (\\\"archive\\\", \\\"dir\\\")]:\\n        if kind == \\\"file\\\":\\n            ok = os.path.isfile(p)\\n            size = os.path.getsize(p) if ok else -1\\n        else:\\n            ok = os.path.isdir(p)\\n            size = len(os.listdir(p)) if ok else -1\\n        state.append({\\\"path\\\": p, \\\"kind\\\": kind, \\\"present\\\": ok, \\\"measure\\\": size})\\n    blob = json.dumps(state, sort_keys=True).encode()\\n    return hashlib.sha256(blob).hexdigest()[:16], sum(1 for s in state if s[\\\"present\\\"])\\n\\n\\ndef verify():\\n    print(\\\"== VERIFICATION ==\\\")\\n    f, count = fingerprint()\\n    ch = sha256(\\\"contract.yaml\\\")\\n    print(f\\\"  notes.txt regular file: {os.path.isfile('notes.txt')}\\\")\\n    print(f\\\"  archive is directory: {os.path.isdir('archive')}\\\")\\n    print(f\\\"  contract.yaml checksum intact: {ch == CONTRACT_SHA}\\\")\\n    print(f\\\"  resources reconciled: {count}/2\\\")\\n    print(f\\\"  STATE FINGERPRINT: {f}\\\")\\n    return count == 2 and ch == CONTRACT_SHA\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    now = datetime.now(timezone.utc).strftime(\\\"%Y-%m-%dT%H:%M:%SZ\\\")\\n    print(f\\\"plan-001 apply @ {now}\\\")\\n    preflight()\\n    print(\\\"== APPLY ==\\\")\\n    a1_ensure_file()\\n    a2_ensure_dir()\\n    if verify():\\n        print(\\\"RESULT: desired state (2/2 reconciled)\\\")\\n    else:\\n        print(\\\"RESULT: verification FAILED\\\")\\n        sys.exit(1)\\n\",\"path\":\"apply_plan.py\"}"}}]}}]}

